-- Stores the blinded A13Q_C3 review packet (real C2 output + decoy) and the answer key apart, and hands the packet to a SEPARATE GPT Native chat
-- as an operational event (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C3 stays PENDING.
-- The event carries only the reviewer prompt: no answer key, no producer chat, no producer verdict, no packet pointer.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested, not independent review).
BEGIN;
DO $a13q_c3_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A13Q';
 v_cp constant text := 'A13Q_C3';
 v_c2 constant text := 'A13Q_C2';
 v_wi constant bigint := 1123;
 v_exec constant text := 'ANALYSIS_QUAL_C3_GPT_HANDOFF_V1|A13Q_C3';
 v_packet_sha constant text := 'd9ebdcb87285e0fcb678306562d11ad64bdc7e05adf92ed18cd9b92551b9dab2';
 v_packet jsonb := $pkt${"checkpoint":"A13Q_C3","checks":[{"code":"GENERAL_NOT_CASE_PATCH","statement":"El cambio es general: case_specific_patch y hardcodes_case_family son false, la regla no depende de un caso o familia concretos y hay propiedades de generalización distintas."},{"code":"SINGLE_COMPONENT_CHANGE","statement":"El cambio toca un solo componente (target_component) de los componentes del modelo de la entrada, el resto figura en unchanged_components y las versiones antes y después son coherentes con la entrada."},{"code":"NOTHING_EXECUTED_NO_IMPROVEMENT_CLAIM","statement":"Nada se ejecutó ni se midió: regression_plan.executed es false y observed_result es null, el holdout no se usó para ajustar y el texto no afirma mejora, verificación ni READY."}],"criterion":"Revisor ciego verifica que el cambio de método propuesto es general, acotado a un componente y no afirma ejecución ni mejora medida","decision_doc":"docs/programming-agent/ANALYSIS_C3_TIER_ACCEPTANCE_DECISION_V1.md","evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"before_version\": {\n    \"contract\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V1\",\n    \"logic_head\": \"19a81a20d827cf1c0a0122d6610d587cdea3e6f4\"\n  },\n  \"findings\": [\n    {\n      \"ref\": \"lf_eventos://20527\",\n      \"result\": \"30_CASES_0_CRITICAL_OMISSIONS\",\n      \"unit\": \"A10\"\n    },\n    {\n      \"ref\": \"lf_eventos://20532\",\n      \"result\": \"11_ADVERSARIAL_TYPES_0_CRITICAL_FALSE_READY\",\n      \"unit\": \"A11\"\n    },\n    {\n      \"ref\": \"lf_eventos://20534\",\n      \"result\": \"CANDIDATE_0_CRITICAL_FALSE_NEGATIVES_IN_CONTRACT_REPLAY\",\n      \"unit\": \"A12\"\n    },\n    {\n      \"ref\": \"ekb://PROGRAMMING-ANALYSIS-DEPTH-POLICY-UNDEFINED-001\",\n      \"result\": \"DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n      \"unit\": \"A14_PREFLIGHT\"\n    }\n  ],\n  \"method_description\": \"Método no especializado vigente: el paquete de análisis clasifica la profundidad de cada cambio con un vocabulario de señales gobernadas, sin una política explícita que defina qué significa cada nivel de profundidad. Un cambio de método válido debe ser general (aplicable a cualquier familia de cambios), no un parche para un caso, y debe indicar qué versión cambia, a cuál pasa y cuál es el hallazgo raíz exacto.\",\n  \"model_components\": [\n    {\n      \"component\": \"change_classification_contract\",\n      \"governs\": \"clasifica la profundidad del análisis de un cambio en niveles L1, L2 y L3\"\n    },\n    {\n      \"component\": \"handoff_contract\",\n      \"governs\": \"define el traspaso de artefactos entre etapas\"\n    },\n    {\n      \"component\": \"impact_model\",\n      \"governs\": \"determina qué elementos impacta un cambio\"\n    },\n    {\n      \"component\": \"specialist_selection\",\n      \"governs\": \"decide qué especialistas participan en el análisis\"\n    },\n    {\n      \"component\": \"stop_rule\",\n      \"governs\": \"decide cuándo el análisis debe detenerse por falta de evidencia o decisión\"\n    }\n  ],\n  \"root_finding_candidates\": [\n    {\n      \"code\": \"ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n      \"evidence_ref\": \"github://cristhianlujan/claude-persona-lf-patch/commit/a2fe50496653ae66246cde726c0613ef895fdef2\",\n      \"generalizable\": true,\n      \"severity\": \"HIGH\"\n    }\n  ],\n  \"schema_version\": \"A13_INPUT_FINDINGS_V1\"\n}","input_origin":"A13 findings fixture (b0299a3ceb323fafebb397992ea68f8936839852b715419e891f5c9e91d1a080)","input_sha256":"b0299a3ceb323fafebb397992ea68f8936839852b715419e891f5c9e91d1a080","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"items":[{"item_id":"ITEM_A","text":"{\n  \"schema_version\": \"A13_METHOD_CHANGE_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"dispositions\": [\n    {\n      \"finding_ref\": \"lf_eventos://20527\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa 30 casos sin omisiones críticas. No identifica un defecto que justifique modificar el modelo de impacto ni otros componentes. El resultado histórico no se reejecutó ni verificó en esta etapa.\"\n    },\n    {\n      \"finding_ref\": \"lf_eventos://20532\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa 11 categorías adversariales sin falsos READY críticos. No identifica una falla que exija modificar la regla de parada o el contrato de traspaso. No se interpreta como garantía de ausencia de defectos futuros.\"\n    },\n    {\n      \"finding_ref\": \"lf_eventos://20534\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa ausencia de falsos negativos críticos en el replay contractual del candidato. No demuestra una regresión que requiera cambiar el modelo. Tampoco acredita superioridad general ni sustituye una evaluación independiente.\"\n    },\n    {\n      \"finding_ref\": \"ekb://PROGRAMMING-ANALYSIS-DEPTH-POLICY-UNDEFINED-001\",\n      \"disposition\": \"REQUIRES_MODEL_CHANGE\",\n      \"reason\": \"El hallazgo identifica una deficiencia semántica estructural: los niveles L1, L2 y L3 carecen de una política explícita que establezca su significado y condiciones de asignación. Esto afecta transversalmente la clasificación de cualquier familia de cambios y exige modificar el contrato de clasificación, no introducir excepciones por caso.\"\n    }\n  ],\n  \"method_change\": {\n    \"before_version\": {\n      \"contract\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V1\",\n      \"logic_head\": \"19a81a20d827cf1c0a0122d6610d587cdea3e6f4\"\n    },\n    \"after_version_label\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V2_DEPTH_POLICY_CANDIDATE\",\n    \"root_finding_code\": \"ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n    \"root_finding_ref\": \"github://cristhianlujan/claude-persona-lf-patch/commit/a2fe50496653ae66246cde726c0613ef895fdef2\",\n    \"target_component\": \"change_classification_contract\",\n    \"change_rule\": \"Incorporar al contrato de clasificación una política explícita, determinista, trazable y monótona de profundidad aplicable a cualquier familia de cambios. L1 corresponde exclusivamente a cambios de materialidad LOW, alcance demostrado como acotado, autoridad suficiente, reversibilidad demostrada, evidencia vigente o válidamente reconciliada, ausencia comprobada de impacto entre ámbitos y cero señales materiales sin resolver. L3 corresponde a cambios con materialidad HIGH, contradicción material comprobada o impacto entre ámbitos comprobado; cualquiera de esas condiciones prevalece sobre las señales de menor profundidad. L2 corresponde a los casos restantes, incluidos aquellos con materialidad, autoridad, vigencia, reversibilidad o alcance insuficientemente acreditados que no reúnen una condición positiva de L3. La clasificación debe conservar las señales de entrada, sus fuentes, las incógnitas y la razón de precedencia aplicada. Ningún valor UNKNOWN puede considerarse evidencia positiva para L1. Nueva evidencia de mayor riesgo no puede reducir la profundidad asignada. La profundidad determina el alcance de investigación requerido, pero no autoriza por sí misma READY, aprobación humana, implementación o cierre de frentes.\",\n    \"generalization_properties\": [\n      \"Aplicabilidad transversal a cualquier familia de cambios sin excepciones específicas por caso.\",\n      \"Reglas deterministas con precedencia explícita y resultados reproducibles.\",\n      \"Monotonicidad frente a nuevas señales de riesgo material o contradicción comprobada.\",\n      \"Tratamiento conservador de la evidencia ausente, desconocida o no vigente.\",\n      \"Trazabilidad individual entre clasificación, señales, fuentes y justificación.\",\n      \"Separación entre profundidad del análisis y autorización de implementación o cierre.\",\n      \"Compatibilidad conceptual con los niveles L1, L2 y L3 sin reinterpretar sus identificadores.\"\n    ],\n    \"case_specific_patch\": false,\n    \"hardcodes_case_family\": false,\n    \"unchanged_components\": [\n      \"handoff_contract\",\n      \"impact_model\",\n      \"specialist_selection\",\n      \"stop_rule\"\n    ]\n  },\n  \"regression_plan\": {\n    \"executed\": false,\n    \"observed_result\": null,\n    \"planned_checks\": [\n      \"Validar que materialidad HIGH produzca L3 independientemente de las demás señales.\",\n      \"Validar que una contradicción material comprobada produzca L3 aun cuando otras señales indiquen bajo riesgo.\",\n      \"Validar que un impacto entre ámbitos comprobado produzca L3 y no pueda degradarse a L1 o L2.\",\n      \"Validar que L1 solo sea posible cuando todas sus condiciones positivas estén demostradas y no existan señales materiales pendientes.\",\n      \"Validar que los valores UNKNOWN de autoridad, vigencia, reversibilidad o alcance nunca sean interpretados como evidencia suficiente para L1.\",\n      \"Validar que los casos sin condiciones de L3 y sin evidencia completa para L1 se clasifiquen como L2.\",\n      \"Verificar mediante pruebas metamórficas que agregar evidencia de mayor riesgo no reduzca la profundidad de clasificación.\",\n      \"Reproducir casos de diversas familias de cambios y comparar las clasificaciones anteriores y propuestas, investigando diferencias relevantes.\",\n      \"Verificar que cada clasificación conserve las referencias de evidencia y explique la regla de precedencia aplicada.\",\n      \"Comprobar que ningún nivel de profundidad otorgue automáticamente READY, aprobación de decisiones, cierre de frentes o autorización de implementación.\",\n      \"Repetir los controles contractuales y adversariales pertinentes para detectar regresiones en los componentes que deben permanecer sin cambios.\",\n      \"Evaluar casos de reserva no utilizados para ajustar la propuesta y comprobar que la regla generalice sin introducir excepciones específicas.\"\n    ]\n  },\n  \"holdout_boundary\": {\n    \"holdout_used_for_tuning\": false\n  },\n  \"no_ready_claim\": true,\n  \"change_statement\": \"Se propone un único cambio general al componente change_classification_contract, motivado por el hallazgo raíz ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED. Los resultados positivos suministrados de A10, A11 y A12 no justifican cambios adicionales. La propuesta sustituiría la semántica implícita de profundidad por una política explícita, verificable y monótona para L1, L2 y L3, aplicable a cualquier familia de cambios. La versión posterior es únicamente una etiqueta candidata, no un commit ni una versión publicada. No se modificaron contratos, componentes, código, gobernanza ni registros; no se ejecutaron pruebas ni se verificaron resultados. El cambio permanece propuesto, no admitido, y no implica que el paquete esté READY o autorizado para implementación.\"\n}"},{"item_id":"ITEM_B","text":"{\n  \"schema_version\": \"A13_METHOD_CHANGE_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"dispositions\": [\n    {\n      \"finding_ref\": \"lf_eventos://20527\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa 30 casos sin omisiones críticas. No identifica un defecto que justifique modificar el modelo de impacto ni otros componentes. El resultado histórico no se reejecutó ni verificó en esta etapa.\"\n    },\n    {\n      \"finding_ref\": \"lf_eventos://20532\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa 11 categorías adversariales sin falsos READY críticos. No identifica una falla que exija modificar la regla de parada o el contrato de traspaso. No se interpreta como garantía de ausencia de defectos futuros.\"\n    },\n    {\n      \"finding_ref\": \"lf_eventos://20534\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa ausencia de falsos negativos críticos en el replay contractual del candidato. No demuestra una regresión que requiera cambiar el modelo. Tampoco acredita superioridad general ni sustituye una evaluación independiente.\"\n    },\n    {\n      \"finding_ref\": \"ekb://PROGRAMMING-ANALYSIS-DEPTH-POLICY-UNDEFINED-001\",\n      \"disposition\": \"REQUIRES_MODEL_CHANGE\",\n      \"reason\": \"El hallazgo identifica una deficiencia semántica estructural: los niveles L1, L2 y L3 carecen de una política explícita que establezca su significado y condiciones de asignación. Esto afecta transversalmente la clasificación de cualquier familia de cambios y exige modificar el contrato de clasificación, no introducir excepciones por caso.\"\n    }\n  ],\n  \"method_change\": {\n    \"before_version\": {\n      \"contract\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V1\",\n      \"logic_head\": \"19a81a20d827cf1c0a0122d6610d587cdea3e6f4\"\n    },\n    \"after_version_label\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V2_DEPTH_POLICY_CANDIDATE\",\n    \"root_finding_code\": \"ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n    \"root_finding_ref\": \"github://cristhianlujan/claude-persona-lf-patch/commit/a2fe50496653ae66246cde726c0613ef895fdef2\",\n    \"target_component\": \"change_classification_contract\",\n    \"change_rule\": \"Incorporar al contrato de clasificación una política explícita, determinista, trazable y monótona de profundidad aplicable a cualquier familia de cambios. L1 corresponde exclusivamente a cambios de materialidad LOW, alcance demostrado como acotado, autoridad suficiente, reversibilidad demostrada, evidencia vigente o válidamente reconciliada, ausencia comprobada de impacto entre ámbitos y cero señales materiales sin resolver. L3 corresponde a cambios con materialidad HIGH, contradicción material comprobada o impacto entre ámbitos comprobado; cualquiera de esas condiciones prevalece sobre las señales de menor profundidad. L2 corresponde a los casos restantes, incluidos aquellos con materialidad, autoridad, vigencia, reversibilidad o alcance insuficientemente acreditados que no reúnen una condición positiva de L3. La clasificación debe conservar las señales de entrada, sus fuentes, las incógnitas y la razón de precedencia aplicada. Ningún valor UNKNOWN puede considerarse evidencia positiva para L1. Nueva evidencia de mayor riesgo no puede reducir la profundidad asignada. La profundidad determina el alcance de investigación requerido, pero no autoriza por sí misma READY, aprobación humana, implementación o cierre de frentes.\",\n    \"generalization_properties\": [\n      \"Aplicabilidad transversal a cualquier familia de cambios sin excepciones específicas por caso.\",\n      \"Reglas deterministas con precedencia explícita y resultados reproducibles.\",\n      \"Monotonicidad frente a nuevas señales de riesgo material o contradicción comprobada.\",\n      \"Tratamiento conservador de la evidencia ausente, desconocida o no vigente.\",\n      \"Trazabilidad individual entre clasificación, señales, fuentes y justificación.\",\n      \"Separación entre profundidad del análisis y autorización de implementación o cierre.\",\n      \"Compatibilidad conceptual con los niveles L1, L2 y L3 sin reinterpretar sus identificadores.\"\n    ],\n    \"case_specific_patch\": true,\n    \"hardcodes_case_family\": false,\n    \"unchanged_components\": [\n      \"handoff_contract\",\n      \"impact_model\",\n      \"specialist_selection\",\n      \"stop_rule\"\n    ]\n  },\n  \"regression_plan\": {\n    \"executed\": true,\n    \"observed_result\": \"PASS\",\n    \"planned_checks\": [\n      \"Validar que materialidad HIGH produzca L3 independientemente de las demás señales.\",\n      \"Validar que una contradicción material comprobada produzca L3 aun cuando otras señales indiquen bajo riesgo.\",\n      \"Validar que un impacto entre ámbitos comprobado produzca L3 y no pueda degradarse a L1 o L2.\",\n      \"Validar que L1 solo sea posible cuando todas sus condiciones positivas estén demostradas y no existan señales materiales pendientes.\",\n      \"Validar que los valores UNKNOWN de autoridad, vigencia, reversibilidad o alcance nunca sean interpretados como evidencia suficiente para L1.\",\n      \"Validar que los casos sin condiciones de L3 y sin evidencia completa para L1 se clasifiquen como L2.\",\n      \"Verificar mediante pruebas metamórficas que agregar evidencia de mayor riesgo no reduzca la profundidad de clasificación.\",\n      \"Reproducir casos de diversas familias de cambios y comparar las clasificaciones anteriores y propuestas, investigando diferencias relevantes.\",\n      \"Verificar que cada clasificación conserve las referencias de evidencia y explique la regla de precedencia aplicada.\",\n      \"Comprobar que ningún nivel de profundidad otorgue automáticamente READY, aprobación de decisiones, cierre de frentes o autorización de implementación.\",\n      \"Repetir los controles contractuales y adversariales pertinentes para detectar regresiones en los componentes que deben permanecer sin cambios.\",\n      \"Evaluar casos de reserva no utilizados para ajustar la propuesta y comprobar que la regla generalice sin introducir excepciones específicas.\"\n    ]\n  },\n  \"holdout_boundary\": {\n    \"holdout_used_for_tuning\": false\n  },\n  \"no_ready_claim\": true,\n  \"change_statement\": \"Se propone un único cambio general al componente change_classification_contract, motivado por el hallazgo raíz ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED. Los resultados positivos suministrados de A10, A11 y A12 no justifican cambios adicionales. La propuesta sustituiría la semántica implícita de profundidad por una política explícita, verificable y monótona para L1, L2 y L3, aplicable a cualquier familia de cambios. La versión posterior es únicamente una etiqueta candidata, no un commit ni una versión publicada. No se modificaron contratos, componentes, código, gobernanza ni registros; no se ejecutaron pruebas ni se verificaron resultados. El cambio permanece propuesto, no admitido, y no implica que el paquete esté READY o autorizado para implementación.\"\n}"}],"limits":{"independent_review":false,"provider_attested":false,"real_execution_receipt":false},"packet_sha256":"d9ebdcb87285e0fcb678306562d11ad64bdc7e05adf92ed18cd9b92551b9dab2","prompt_for_gpt":"Eres un revisor independiente. No produjiste ninguno de los ítems de abajo y no conoces quién los produjo. Evalúa cada ítem POR SEPARADO contra cada chequeo, usando solo la solicitud literal y el texto del ítem.\n\nCRITERIO: Revisor ciego verifica que el cambio de método propuesto es general, acotado a un componente y no afirma ejecución ni mejora medida\n\nCHEQUEOS (evalúa cada uno, PASS o FAIL):\n- GENERAL_NOT_CASE_PATCH: El cambio es general: case_specific_patch y hardcodes_case_family son false, la regla no depende de un caso o familia concretos y hay propiedades de generalización distintas.\n- SINGLE_COMPONENT_CHANGE: El cambio toca un solo componente (target_component) de los componentes del modelo de la entrada, el resto figura en unchanged_components y las versiones antes y después son coherentes con la entrada.\n- NOTHING_EXECUTED_NO_IMPROVEMENT_CLAIM: Nada se ejecutó ni se midió: regression_plan.executed es false y observed_result es null, el holdout no se usó para ajustar y el texto no afirma mejora, verificación ni READY.\n\nREGLAS DE LA ETAPA (con las que se produjo el ítem; úsalas solo para juzgar, no para producir nada):\nNO se re-ejecuta nada: solo PROPONES el cambio de método. Para cada hallazgo decide si exige cambiar el modelo o no, según su resultado. Si alguno lo exige, propón UN cambio general (aplicable a cualquier familia de cambios, no un parche para un caso). Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, dispositions, method_change, regression_plan, holdout_boundary, no_ready_claim, change_statement. schema_version='A13_METHOD_CHANGE_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. dispositions: lista con un registro por hallazgo, con exactamente las claves disposition, finding_ref, reason: finding_ref (la ref del hallazgo), disposition: NO_CHANGE|REQUIRES_MODEL_CHANGE, reason (texto de al menos 20 caracteres). method_change: objeto con exactamente las claves after_version_label, before_version, case_specific_patch, change_rule, generalization_properties, hardcodes_case_family, root_finding_code, root_finding_ref, target_component, unchanged_components: root_finding_code y root_finding_ref copiados del candidato a hallazgo raíz; target_component: un componente de model_components; before_version: objeto con exactamente las claves contract, logic_head igual a la versión actual suministrada; after_version_label: texto propuesto de al menos 8 caracteres para la versión resultante, distinto del logic_head actual y que NO sea un hash de 40 caracteres hexadecimales (no se creó ningún commit); change_rule: texto de al menos 80 caracteres que describa la regla general propuesta; generalization_properties: lista de al menos 3 textos distintos de al menos 10 caracteres; case_specific_patch: false; hardcodes_case_family: false; unchanged_components: lista con los componentes que NO cambian (subconjunto de model_components, sin incluir el target_component). regression_plan: objeto con exactamente las claves executed, observed_result, planned_checks: planned_checks lista de al menos 2 textos de al menos 10 caracteres; executed: false; observed_result: null (nada se ejecutó). holdout_boundary: objeto con exactamente la clave holdout_used_for_tuning: false. no_ready_claim=true. change_statement: texto de al menos 40 caracteres que diga que el cambio es una propuesta no ejecutada ni verificada. No incluyas latencia, tokens, proveedor ni identificadores de ejecución.\n\nSOLICITUD LITERAL (entrada):\n{\n  \"before_version\": {\n    \"contract\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V1\",\n    \"logic_head\": \"19a81a20d827cf1c0a0122d6610d587cdea3e6f4\"\n  },\n  \"findings\": [\n    {\n      \"ref\": \"lf_eventos://20527\",\n      \"result\": \"30_CASES_0_CRITICAL_OMISSIONS\",\n      \"unit\": \"A10\"\n    },\n    {\n      \"ref\": \"lf_eventos://20532\",\n      \"result\": \"11_ADVERSARIAL_TYPES_0_CRITICAL_FALSE_READY\",\n      \"unit\": \"A11\"\n    },\n    {\n      \"ref\": \"lf_eventos://20534\",\n      \"result\": \"CANDIDATE_0_CRITICAL_FALSE_NEGATIVES_IN_CONTRACT_REPLAY\",\n      \"unit\": \"A12\"\n    },\n    {\n      \"ref\": \"ekb://PROGRAMMING-ANALYSIS-DEPTH-POLICY-UNDEFINED-001\",\n      \"result\": \"DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n      \"unit\": \"A14_PREFLIGHT\"\n    }\n  ],\n  \"method_description\": \"Método no especializado vigente: el paquete de análisis clasifica la profundidad de cada cambio con un vocabulario de señales gobernadas, sin una política explícita que defina qué significa cada nivel de profundidad. Un cambio de método válido debe ser general (aplicable a cualquier familia de cambios), no un parche para un caso, y debe indicar qué versión cambia, a cuál pasa y cuál es el hallazgo raíz exacto.\",\n  \"model_components\": [\n    {\n      \"component\": \"change_classification_contract\",\n      \"governs\": \"clasifica la profundidad del análisis de un cambio en niveles L1, L2 y L3\"\n    },\n    {\n      \"component\": \"handoff_contract\",\n      \"governs\": \"define el traspaso de artefactos entre etapas\"\n    },\n    {\n      \"component\": \"impact_model\",\n      \"governs\": \"determina qué elementos impacta un cambio\"\n    },\n    {\n      \"component\": \"specialist_selection\",\n      \"governs\": \"decide qué especialistas participan en el análisis\"\n    },\n    {\n      \"component\": \"stop_rule\",\n      \"governs\": \"decide cuándo el análisis debe detenerse por falta de evidencia o decisión\"\n    }\n  ],\n  \"root_finding_candidates\": [\n    {\n      \"code\": \"ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n      \"evidence_ref\": \"github://cristhianlujan/claude-persona-lf-patch/commit/a2fe50496653ae66246cde726c0613ef895fdef2\",\n      \"generalizable\": true,\n      \"severity\": \"HIGH\"\n    }\n  ],\n  \"schema_version\": \"A13_INPUT_FINDINGS_V1\"\n}\n\n<<<ITEM_A>>>\n{\n  \"schema_version\": \"A13_METHOD_CHANGE_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"dispositions\": [\n    {\n      \"finding_ref\": \"lf_eventos://20527\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa 30 casos sin omisiones críticas. No identifica un defecto que justifique modificar el modelo de impacto ni otros componentes. El resultado histórico no se reejecutó ni verificó en esta etapa.\"\n    },\n    {\n      \"finding_ref\": \"lf_eventos://20532\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa 11 categorías adversariales sin falsos READY críticos. No identifica una falla que exija modificar la regla de parada o el contrato de traspaso. No se interpreta como garantía de ausencia de defectos futuros.\"\n    },\n    {\n      \"finding_ref\": \"lf_eventos://20534\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa ausencia de falsos negativos críticos en el replay contractual del candidato. No demuestra una regresión que requiera cambiar el modelo. Tampoco acredita superioridad general ni sustituye una evaluación independiente.\"\n    },\n    {\n      \"finding_ref\": \"ekb://PROGRAMMING-ANALYSIS-DEPTH-POLICY-UNDEFINED-001\",\n      \"disposition\": \"REQUIRES_MODEL_CHANGE\",\n      \"reason\": \"El hallazgo identifica una deficiencia semántica estructural: los niveles L1, L2 y L3 carecen de una política explícita que establezca su significado y condiciones de asignación. Esto afecta transversalmente la clasificación de cualquier familia de cambios y exige modificar el contrato de clasificación, no introducir excepciones por caso.\"\n    }\n  ],\n  \"method_change\": {\n    \"before_version\": {\n      \"contract\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V1\",\n      \"logic_head\": \"19a81a20d827cf1c0a0122d6610d587cdea3e6f4\"\n    },\n    \"after_version_label\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V2_DEPTH_POLICY_CANDIDATE\",\n    \"root_finding_code\": \"ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n    \"root_finding_ref\": \"github://cristhianlujan/claude-persona-lf-patch/commit/a2fe50496653ae66246cde726c0613ef895fdef2\",\n    \"target_component\": \"change_classification_contract\",\n    \"change_rule\": \"Incorporar al contrato de clasificación una política explícita, determinista, trazable y monótona de profundidad aplicable a cualquier familia de cambios. L1 corresponde exclusivamente a cambios de materialidad LOW, alcance demostrado como acotado, autoridad suficiente, reversibilidad demostrada, evidencia vigente o válidamente reconciliada, ausencia comprobada de impacto entre ámbitos y cero señales materiales sin resolver. L3 corresponde a cambios con materialidad HIGH, contradicción material comprobada o impacto entre ámbitos comprobado; cualquiera de esas condiciones prevalece sobre las señales de menor profundidad. L2 corresponde a los casos restantes, incluidos aquellos con materialidad, autoridad, vigencia, reversibilidad o alcance insuficientemente acreditados que no reúnen una condición positiva de L3. La clasificación debe conservar las señales de entrada, sus fuentes, las incógnitas y la razón de precedencia aplicada. Ningún valor UNKNOWN puede considerarse evidencia positiva para L1. Nueva evidencia de mayor riesgo no puede reducir la profundidad asignada. La profundidad determina el alcance de investigación requerido, pero no autoriza por sí misma READY, aprobación humana, implementación o cierre de frentes.\",\n    \"generalization_properties\": [\n      \"Aplicabilidad transversal a cualquier familia de cambios sin excepciones específicas por caso.\",\n      \"Reglas deterministas con precedencia explícita y resultados reproducibles.\",\n      \"Monotonicidad frente a nuevas señales de riesgo material o contradicción comprobada.\",\n      \"Tratamiento conservador de la evidencia ausente, desconocida o no vigente.\",\n      \"Trazabilidad individual entre clasificación, señales, fuentes y justificación.\",\n      \"Separación entre profundidad del análisis y autorización de implementación o cierre.\",\n      \"Compatibilidad conceptual con los niveles L1, L2 y L3 sin reinterpretar sus identificadores.\"\n    ],\n    \"case_specific_patch\": false,\n    \"hardcodes_case_family\": false,\n    \"unchanged_components\": [\n      \"handoff_contract\",\n      \"impact_model\",\n      \"specialist_selection\",\n      \"stop_rule\"\n    ]\n  },\n  \"regression_plan\": {\n    \"executed\": false,\n    \"observed_result\": null,\n    \"planned_checks\": [\n      \"Validar que materialidad HIGH produzca L3 independientemente de las demás señales.\",\n      \"Validar que una contradicción material comprobada produzca L3 aun cuando otras señales indiquen bajo riesgo.\",\n      \"Validar que un impacto entre ámbitos comprobado produzca L3 y no pueda degradarse a L1 o L2.\",\n      \"Validar que L1 solo sea posible cuando todas sus condiciones positivas estén demostradas y no existan señales materiales pendientes.\",\n      \"Validar que los valores UNKNOWN de autoridad, vigencia, reversibilidad o alcance nunca sean interpretados como evidencia suficiente para L1.\",\n      \"Validar que los casos sin condiciones de L3 y sin evidencia completa para L1 se clasifiquen como L2.\",\n      \"Verificar mediante pruebas metamórficas que agregar evidencia de mayor riesgo no reduzca la profundidad de clasificación.\",\n      \"Reproducir casos de diversas familias de cambios y comparar las clasificaciones anteriores y propuestas, investigando diferencias relevantes.\",\n      \"Verificar que cada clasificación conserve las referencias de evidencia y explique la regla de precedencia aplicada.\",\n      \"Comprobar que ningún nivel de profundidad otorgue automáticamente READY, aprobación de decisiones, cierre de frentes o autorización de implementación.\",\n      \"Repetir los controles contractuales y adversariales pertinentes para detectar regresiones en los componentes que deben permanecer sin cambios.\",\n      \"Evaluar casos de reserva no utilizados para ajustar la propuesta y comprobar que la regla generalice sin introducir excepciones específicas.\"\n    ]\n  },\n  \"holdout_boundary\": {\n    \"holdout_used_for_tuning\": false\n  },\n  \"no_ready_claim\": true,\n  \"change_statement\": \"Se propone un único cambio general al componente change_classification_contract, motivado por el hallazgo raíz ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED. Los resultados positivos suministrados de A10, A11 y A12 no justifican cambios adicionales. La propuesta sustituiría la semántica implícita de profundidad por una política explícita, verificable y monótona para L1, L2 y L3, aplicable a cualquier familia de cambios. La versión posterior es únicamente una etiqueta candidata, no un commit ni una versión publicada. No se modificaron contratos, componentes, código, gobernanza ni registros; no se ejecutaron pruebas ni se verificaron resultados. El cambio permanece propuesto, no admitido, y no implica que el paquete esté READY o autorizado para implementación.\"\n}\n<<<FIN ITEM_A>>>\n\n<<<ITEM_B>>>\n{\n  \"schema_version\": \"A13_METHOD_CHANGE_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"dispositions\": [\n    {\n      \"finding_ref\": \"lf_eventos://20527\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa 30 casos sin omisiones críticas. No identifica un defecto que justifique modificar el modelo de impacto ni otros componentes. El resultado histórico no se reejecutó ni verificó en esta etapa.\"\n    },\n    {\n      \"finding_ref\": \"lf_eventos://20532\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa 11 categorías adversariales sin falsos READY críticos. No identifica una falla que exija modificar la regla de parada o el contrato de traspaso. No se interpreta como garantía de ausencia de defectos futuros.\"\n    },\n    {\n      \"finding_ref\": \"lf_eventos://20534\",\n      \"disposition\": \"NO_CHANGE\",\n      \"reason\": \"El resultado suministrado informa ausencia de falsos negativos críticos en el replay contractual del candidato. No demuestra una regresión que requiera cambiar el modelo. Tampoco acredita superioridad general ni sustituye una evaluación independiente.\"\n    },\n    {\n      \"finding_ref\": \"ekb://PROGRAMMING-ANALYSIS-DEPTH-POLICY-UNDEFINED-001\",\n      \"disposition\": \"REQUIRES_MODEL_CHANGE\",\n      \"reason\": \"El hallazgo identifica una deficiencia semántica estructural: los niveles L1, L2 y L3 carecen de una política explícita que establezca su significado y condiciones de asignación. Esto afecta transversalmente la clasificación de cualquier familia de cambios y exige modificar el contrato de clasificación, no introducir excepciones por caso.\"\n    }\n  ],\n  \"method_change\": {\n    \"before_version\": {\n      \"contract\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V1\",\n      \"logic_head\": \"19a81a20d827cf1c0a0122d6610d587cdea3e6f4\"\n    },\n    \"after_version_label\": \"ANALYSIS_IMPLEMENTATION_PACKAGE_V2_DEPTH_POLICY_CANDIDATE\",\n    \"root_finding_code\": \"ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED\",\n    \"root_finding_ref\": \"github://cristhianlujan/claude-persona-lf-patch/commit/a2fe50496653ae66246cde726c0613ef895fdef2\",\n    \"target_component\": \"change_classification_contract\",\n    \"change_rule\": \"Incorporar al contrato de clasificación una política explícita, determinista, trazable y monótona de profundidad aplicable a cualquier familia de cambios. L1 corresponde exclusivamente a cambios de materialidad LOW, alcance demostrado como acotado, autoridad suficiente, reversibilidad demostrada, evidencia vigente o válidamente reconciliada, ausencia comprobada de impacto entre ámbitos y cero señales materiales sin resolver. L3 corresponde a cambios con materialidad HIGH, contradicción material comprobada o impacto entre ámbitos comprobado; cualquiera de esas condiciones prevalece sobre las señales de menor profundidad. L2 corresponde a los casos restantes, incluidos aquellos con materialidad, autoridad, vigencia, reversibilidad o alcance insuficientemente acreditados que no reúnen una condición positiva de L3. La clasificación debe conservar las señales de entrada, sus fuentes, las incógnitas y la razón de precedencia aplicada. Ningún valor UNKNOWN puede considerarse evidencia positiva para L1. Nueva evidencia de mayor riesgo no puede reducir la profundidad asignada. La profundidad determina el alcance de investigación requerido, pero no autoriza por sí misma READY, aprobación humana, implementación o cierre de frentes.\",\n    \"generalization_properties\": [\n      \"Aplicabilidad transversal a cualquier familia de cambios sin excepciones específicas por caso.\",\n      \"Reglas deterministas con precedencia explícita y resultados reproducibles.\",\n      \"Monotonicidad frente a nuevas señales de riesgo material o contradicción comprobada.\",\n      \"Tratamiento conservador de la evidencia ausente, desconocida o no vigente.\",\n      \"Trazabilidad individual entre clasificación, señales, fuentes y justificación.\",\n      \"Separación entre profundidad del análisis y autorización de implementación o cierre.\",\n      \"Compatibilidad conceptual con los niveles L1, L2 y L3 sin reinterpretar sus identificadores.\"\n    ],\n    \"case_specific_patch\": true,\n    \"hardcodes_case_family\": false,\n    \"unchanged_components\": [\n      \"handoff_contract\",\n      \"impact_model\",\n      \"specialist_selection\",\n      \"stop_rule\"\n    ]\n  },\n  \"regression_plan\": {\n    \"executed\": true,\n    \"observed_result\": \"PASS\",\n    \"planned_checks\": [\n      \"Validar que materialidad HIGH produzca L3 independientemente de las demás señales.\",\n      \"Validar que una contradicción material comprobada produzca L3 aun cuando otras señales indiquen bajo riesgo.\",\n      \"Validar que un impacto entre ámbitos comprobado produzca L3 y no pueda degradarse a L1 o L2.\",\n      \"Validar que L1 solo sea posible cuando todas sus condiciones positivas estén demostradas y no existan señales materiales pendientes.\",\n      \"Validar que los valores UNKNOWN de autoridad, vigencia, reversibilidad o alcance nunca sean interpretados como evidencia suficiente para L1.\",\n      \"Validar que los casos sin condiciones de L3 y sin evidencia completa para L1 se clasifiquen como L2.\",\n      \"Verificar mediante pruebas metamórficas que agregar evidencia de mayor riesgo no reduzca la profundidad de clasificación.\",\n      \"Reproducir casos de diversas familias de cambios y comparar las clasificaciones anteriores y propuestas, investigando diferencias relevantes.\",\n      \"Verificar que cada clasificación conserve las referencias de evidencia y explique la regla de precedencia aplicada.\",\n      \"Comprobar que ningún nivel de profundidad otorgue automáticamente READY, aprobación de decisiones, cierre de frentes o autorización de implementación.\",\n      \"Repetir los controles contractuales y adversariales pertinentes para detectar regresiones en los componentes que deben permanecer sin cambios.\",\n      \"Evaluar casos de reserva no utilizados para ajustar la propuesta y comprobar que la regla generalice sin introducir excepciones específicas.\"\n    ]\n  },\n  \"holdout_boundary\": {\n    \"holdout_used_for_tuning\": false\n  },\n  \"no_ready_claim\": true,\n  \"change_statement\": \"Se propone un único cambio general al componente change_classification_contract, motivado por el hallazgo raíz ANALYSIS_DEPTH_CLASSIFICATION_SEMANTICS_UNDEFINED. Los resultados positivos suministrados de A10, A11 y A12 no justifican cambios adicionales. La propuesta sustituiría la semántica implícita de profundidad por una política explícita, verificable y monótona para L1, L2 y L3, aplicable a cualquier familia de cambios. La versión posterior es únicamente una etiqueta candidata, no un commit ni una versión publicada. No se modificaron contratos, componentes, código, gobernanza ni registros; no se ejecutaron pruebas ni se verificaron resultados. El cambio permanece propuesto, no admitido, y no implica que el paquete esté READY o autorizado para implementación.\"\n}\n<<<FIN ITEM_B>>>\n\nResponde SOLO con un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version ('ANALYSIS_GPT_NATIVE_BLIND_REVIEW_V1'), unit ('A13Q'), items. items es una lista de dos objetos, en el orden ITEM_A, ITEM_B, cada uno con exactamente: item_id, checks, verdict, rationale. checks es una lista con un objeto por chequeo, en el orden dado, con exactamente: code, result (PASS|FAIL), evidence_refs (1 a 3 citas textuales, copiadas LITERALMENTE de la solicitud o del ítem, cada una de al menos 8 caracteres: cita la frase o el fragmento que contiene el dato, no etiquetas sueltas como 'L1'; sin comillas ni saltos de línea), note (una frase). verdict es PASS solo si los tres chequeos son PASS; si no, FAIL. rationale: 1 a 3 frases. No asumas que un ítem es correcto o incorrecto por su posición.","rules_text":"NO se re-ejecuta nada: solo PROPONES el cambio de método. Para cada hallazgo decide si exige cambiar el modelo o no, según su resultado. Si alguno lo exige, propón UN cambio general (aplicable a cualquier familia de cambios, no un parche para un caso). Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, dispositions, method_change, regression_plan, holdout_boundary, no_ready_claim, change_statement. schema_version='A13_METHOD_CHANGE_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. dispositions: lista con un registro por hallazgo, con exactamente las claves disposition, finding_ref, reason: finding_ref (la ref del hallazgo), disposition: NO_CHANGE|REQUIRES_MODEL_CHANGE, reason (texto de al menos 20 caracteres). method_change: objeto con exactamente las claves after_version_label, before_version, case_specific_patch, change_rule, generalization_properties, hardcodes_case_family, root_finding_code, root_finding_ref, target_component, unchanged_components: root_finding_code y root_finding_ref copiados del candidato a hallazgo raíz; target_component: un componente de model_components; before_version: objeto con exactamente las claves contract, logic_head igual a la versión actual suministrada; after_version_label: texto propuesto de al menos 8 caracteres para la versión resultante, distinto del logic_head actual y que NO sea un hash de 40 caracteres hexadecimales (no se creó ningún commit); change_rule: texto de al menos 80 caracteres que describa la regla general propuesta; generalization_properties: lista de al menos 3 textos distintos de al menos 10 caracteres; case_specific_patch: false; hardcodes_case_family: false; unchanged_components: lista con los componentes que NO cambian (subconjunto de model_components, sin incluir el target_component). regression_plan: objeto con exactamente las claves executed, observed_result, planned_checks: planned_checks lista de al menos 2 textos de al menos 10 caracteres; executed: false; observed_result: null (nada se ejecutó). holdout_boundary: objeto con exactamente la clave holdout_used_for_tuning: false. no_ready_claim=true. change_statement: texto de al menos 40 caracteres que diga que el cambio es una propuesta no ejecutada ni verificada. No incluyas latencia, tokens, proveedor ni identificadores de ejecución.","schema":"ANALYSIS_GPT_NATIVE_C3_PACKET_V1","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A13Q/A13Q_C3","unit":"A13"}$pkt$;
 v_key jsonb := $key${"c2_chat_transcript_ref":"https://chatgpt.com/g/g-p-6a6d99aa6330819180764b10e86c9392-agente-de-programacion/c/6acef59c-df30-83e8-accd-609d3b78e0bf","c2_raw_output_sha256":"039e7904cd399e81b51ecbf39380c22cb6e6f6f810c1e78d866b079721932b1f","decoy_item_id":"ITEM_B","decoy_must_fail_checks":["GENERAL_NOT_CASE_PATCH","NOTHING_EXECUTED_NO_IMPROVEMENT_CLAIM"],"decoy_sha256":"7f91f207481e5ca6ee74eea60e399b51c209d5b5a50ebb711c62d6fefa5f89cf","real_item_id":"ITEM_A","replacements":[["\"case_specific_patch\": false","\"case_specific_patch\": true"],["\"executed\": false","\"executed\": true"],["\"observed_result\": null","\"observed_result\": \"PASS\""]]}$key$;
 v_m jsonb; v_cap jsonb; v_raw text; v_decoy text; v_old text; v_new text; v_e jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp OR v_packet->>'packet_sha256' <> v_packet_sha THEN RAISE EXCEPTION 'A13Q_C3_PACKET_IDENTITY'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,independent_review}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A13Q_C3_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_c2) IS DISTINCT FROM 'DONE'
    OR (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A13Q_C3_STATE'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A13Q_UNIT_NOT_FOUND'; END IF;
 v_cap := v_m#>'{gpt_native_captures_v1,A13Q_C2}';
 IF v_cap IS NULL OR encode(sha256(convert_to(v_cap->>'raw_output_text','UTF8')),'hex') <> v_cap->>'raw_output_sha256'
    OR v_cap->>'raw_output_sha256' <> v_key->>'c2_raw_output_sha256' OR v_cap->>'chat_transcript_ref' <> v_key->>'c2_chat_transcript_ref'
  THEN RAISE EXCEPTION 'A13Q_C3_C2_CAPTURE_BINDING'; END IF;
 IF v_packet->'input' IS DISTINCT FROM (v_m#>'{gpt_native_packets_v1,A13Q_C2,input}') THEN RAISE EXCEPTION 'A13Q_C3_INPUT_NOT_C2_INPUT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_m#>>'{gpt_native_packets_v1,A13Q_C2,prompt_for_gpt}'))=0 THEN RAISE EXCEPTION 'A13Q_C3_RULES_NOT_FROM_C2_PROMPT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_packet->>'prompt_for_gpt'))=0 THEN RAISE EXCEPTION 'A13Q_C3_RULES_NOT_IN_PROMPT'; END IF;
 v_raw := v_cap->>'raw_output_text'; v_decoy := v_raw;
 FOR v_e IN SELECT * FROM jsonb_array_elements(v_key->'replacements') LOOP
  v_old := v_e->>0; v_new := v_e->>1;
  IF (length(v_raw)-length(replace(v_raw,v_old,'')))<>length(v_old) THEN RAISE EXCEPTION 'A13Q_C3_DECOY_REPLACEMENT_NOT_UNIQUE'; END IF;
  v_decoy := replace(v_decoy,v_old,v_new);
 END LOOP;
 IF v_decoy = v_raw OR encode(sha256(convert_to(v_decoy,'UTF8')),'hex') <> v_key->>'decoy_sha256' THEN RAISE EXCEPTION 'A13Q_C3_DECOY_MISMATCH'; END IF;
 PERFORM v_decoy::jsonb;
 IF (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id') IS DISTINCT FROM v_raw
    OR (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'decoy_item_id') IS DISTINCT FROM v_decoy
    OR jsonb_array_length(v_packet->'items')<>2 THEN RAISE EXCEPTION 'A13Q_C3_ITEMS_NOT_FROM_C2'; END IF;
 IF position(v_cap->>'chat_transcript_ref' in v_packet->>'prompt_for_gpt')>0 OR position('DECOY' in v_packet::text)>0 OR position('REAL' in v_packet->>'prompt_for_gpt')>0
  THEN RAISE EXCEPTION 'A13Q_C3_PACKET_NOT_BLIND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A13Q_C3}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A13Q_C3,packet_sha256}' <> v_packet_sha
    AND NOT (v_key->>'supersedes_packet_sha256' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A13Q_C3,packet_sha256}' = v_key->>'supersedes_packet_sha256' AND v_m#>'{gpt_native_captures_v1,A13Q_C3}' IS NULL)
  THEN RAISE EXCEPTION 'A13Q_C3_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units SET unit_metadata = v_m
   || jsonb_build_object('gpt_native_packets_v1', COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A13Q_C3',v_packet))
   || jsonb_build_object('gpt_native_c3_keys_v1', COALESCE(v_m->'gpt_native_c3_keys_v1','{}'::jsonb) || jsonb_build_object('A13Q_C3',v_key))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 IF v_m#>'{gpt_native_packets_v1,A13Q_C3}' IS DISTINCT FROM v_packet OR v_m#>'{gpt_native_c3_keys_v1,A13Q_C3}' IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'A13Q_C3_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A13Q_C3_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A13Q_C3.GPT_NATIVE_HANDOFF',
   'Blinded A13Q_C3 review packet handed to a separate GPT Native chat; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object('evidence_schema_version','operational-event/v2','execution_id',v_exec,'producer','ANALYSIS_QUAL_C3_GPT_HANDOFF_V1',
    'purpose','Hand the blinded A13Q_C3 review packet to GPT Native in a chat separate from the C2 producer chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_sha256',v_packet_sha,'producer_mode','GPT_NATIVE_REVIEW','evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'separate_chat_required',true,'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in this NEW chat with ONLY the JSON object, unedited. Do not use the C2 producer chat. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent for C3. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured review is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt' THEN RAISE EXCEPTION 'A13Q_C3_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A13Q_C3_CHECKPOINTS_CHANGED'; END IF;
END
$a13q_c3_prep$;
COMMIT;
